SPECIALTY_CARDS.benefits.questions=[choice('purpose','What would you like to accomplish for your employees?','¿Qué deseas lograr para tus empleados?','Use the employer’s goal to guide a group-health or additional-benefits review.','Usa el objetivo para guiar revisión de salud grupal o beneficios adicionales.',{options:[['start_group','Start group health coverage','Comenzar cobertura de salud grupal'],['review_group','Review / replace our group health plan','Revisar / reemplazar plan de salud grupal'],['add','Add employee benefits','Agregar beneficios para empleados'],['costs','Review benefit costs','Revisar costos de beneficios'],['unsure','Help me decide where to start','Ayúdame a decidir por dónde comenzar']]}),...benefitsOriginal,
 choice('group_status','What group health arrangement is in place today?','¿Qué arreglo de salud grupal existe hoy?','Confirm the current group arrangement and employee/dependent needs before comparing coverage.','Confirma arreglo grupal y necesidades de empleados y dependientes antes de comparar.',{whenAll:[staff,{field:'purpose',values:['start_group','review_group','costs','unsure','unknown']}],options:[['none','No group health plan','Sin plan de salud grupal'],['insured','An insured group health plan','Plan grupal asegurado'],['funded','Self-funded / level-funded arrangement','Arreglo autofinanciado / de financiamiento nivelado'],['hra','Reimbursement arrangement / HRA','Arreglo de reembolso / HRA'],['other','Other','Otro']]}),
 choice('group_goal','Who would you like the group coverage to include?','¿A quién deseas incluir en la cobertura grupal?','Confirm eligibility classes, dependents, and employer contribution preferences during a benefits review.','Confirma clases elegibles, dependientes y preferencias de aportación durante revisión.',{whenAll:[staff,{field:'purpose',values:['start_group','review_group']}],options:[['employees','Employees','Empleados'],['dependents','Employees and dependents','Empleados y dependientes'],['compare','Help me compare approaches','Ayúdame a comparar enfoques']]}),
]
// Move coverage confirmations later: a new group-health shopper need not mistake DCBG for primary coverage.
SPECIALTY_CARDS.benefits.questions=SPECIALTY_CARDS.benefits.questions.map(q=>q.id==='covered'?{...q,when:undefined,whenAll:[staff,{field:'purpose',values:['add','costs','unsure','unknown']}]}:q)

// TSP: client circumstances determine the review agenda; keeping the account remains an explicit option.
const tspPrevious=SPECIALTY_CARDS.tsp.questions
SPECIALTY_CARDS.tsp.questions=[
 choice('goal','What would you most like help understanding about your TSP or federal retirement?','¿Qué deseas entender mejor de tu TSP o jubilación federal?','Start with the stated decision and compare available options without assuming money should move.','Comienza con la decisión indicada y compara opciones sin suponer que debas mover dinero.',{options:[['understand','Understand and manage my current TSP','Entender y administrar mi TSP actual'],['income','Coordinate retirement income and benefits','Coordinar ingresos y beneficios de jubilación'],['compare','Compare keeping TSP with alternatives','Comparar mantener TSP con alternativas'],['beneficiary','Handle an inherited / beneficiary account','Gestionar cuenta heredada / de beneficiario'],['unsure','Help me find a starting point','Ayúdame a encontrar un punto de partida']]}),
 ...tspPrevious.map(q=>q.id==='service'?{...q,options:[['civilian','Active federal civilian employee','Empleado civil federal activo'],['uniformed','Active uniformed service member','Miembro activo de servicio uniformado'],['former','Separated / retired federal or uniformed service','Separado / jubilado del servicio federal o uniformado'],['beneficiary','Spouse / beneficiary','Cónyuge / beneficiario'],['other','Other / exploring','Otro / explorando']] as [string,string,string][]}:q.id==='timeline'?{...q,when:{field:'service',values:['civilian','uniformed','former','other','unknown']}}:q.id==='loan'?{...q,when:undefined,whenAll:[{field:'account',values:['yes']},{field:'service',values:['civilian','uniformed','former','other','unknown']}]}:q.id==='options'?{...q,label:c('Have you compared keeping TSP with alternatives, including fees, liquidity, taxes, benefits, and restrictions?','¿Comparaste mantener TSP con alternativas, incluidos cargos, liquidez, impuestos, beneficios y restricciones?'),when:undefined,whenAll:[{field:'account',values:['yes']},{field:'goal',values:['compare']}]}:q.id==='pension'?{...q,when:{field:'service',values:['civilian','uniformed','former','other','unknown']}}:q),
 choice('taxmix','Do you know whether your account has traditional, Roth, or both types of money?','¿Sabes si tu cuenta tiene dinero tradicional, Roth o ambos?','Confirm traditional, Roth, and any other relevant account components from official records before discussing tax treatment.','Confirma componentes tradicionales, Roth y otros relevantes en registros oficiales antes de revisar impuestos.',{when:{field:'account',values:['yes']},options:[['traditional','Traditional','Tradicional'],['roth','Roth','Roth'],['both','Both','Ambos']]}),
 choice('income_review','Have dependable income and essential retirement spending been reviewed together?','¿Se revisaron juntos ingresos confiables y gastos esenciales de jubilación?','Build a coordinated income plan using separate pension, Social Security, TSP, healthcare, and spending estimates.','Crea un plan coordinado con estimaciones separadas de pensión, Seguro Social, TSP, salud y gastos.',{when:{field:'service',values:['civilian','uniformed','former','other','unknown']},reviewValues:['no']}),
 choice('healthcare_review','Have health coverage and survivor benefits been considered in your transition plan?','¿Se consideraron cobertura de salud y beneficios de sobrevivientes en tu plan de transición?','Confirm healthcare continuation, survivor choices, and transition timing with the appropriate benefits office.','Confirma continuidad de salud, opciones de sobrevivientes y fechas con la oficina de beneficios correspondiente.',{when:{field:'service',values:['civilian','uniformed','former','other','unknown']},reviewValues:['no']}),
]
SPECIALTY_CARDS.tsp.source=[{label:'Official TSP account and educational resources',url:'https://www.tsp.gov/'},{label:'OPM: retirement services and planning',url:'https://www.opm.gov/retirement-center/'},{label:'OPM: survivor benefits',url:'https://www.opm.gov/retirement-center/survivor-benefits/'},{label:'FINRA: retirement account considerations',url:'https://www.finra.org/investors/learn-to-invest/types-investments/retirement/managing-retirement-income/taxation-retirement-income'}]
SPECIALTY_CARDS.tsp.note=c('Independent educational planning review, not affiliated with TSP or the federal government. Retaining TSP is an option to compare. No rollover, conversion, investment allocation, or beneficiary distribution is recommended. An inherited account requires specialist review. Confirm current rules and account details directly with TSP and the relevant benefits office.','Revisión educativa independiente sin afiliación con TSP ni el gobierno federal. Mantener TSP es una opción a comparar. No se recomiendan transferencias, conversiones, asignaciones ni distribuciones heredadas. Las cuentas heredadas requieren revisión especializada. Confirma reglas y detalles con TSP y la oficina de beneficios.')

// Tax: clarify the event stage and route uncertainty to confirmation, not a speculative savings number.
SPECIALTY_CARDS.tax.questions=SPECIALTY_CARDS.tax.questions.map(q=>q.id==='changes'?{...q,help:c('Select the events that apply. A planned sale and an already completed sale have different planning constraints.','Selecciona eventos aplicables. Una venta prevista y una completada tienen restricciones distintas.')}:q.id==='revenue'?{...q,help:c('Gross business revenue, not profit, owner wages, or household income. A published revenue marker is only a starting point for partner review.','Ingresos brutos del negocio, no utilidad, sueldo del dueño ni ingresos del hogar. Un marcador publicado solo inicia la revisión del socio.')}:q.id==='w2_income'?{...q,help:c('Your own W-2 wages, not combined household income. Do not add business revenue here.','Tus salarios W-2 personales, no ingresos combinados del hogar. No agregues ingresos brutos del negocio aquí.')}:q)
SPECIALTY_CARDS.tax.questions.push(choice('event_timing','When is the planned sale or retirement tax decision expected?','¿Cuándo esperas la venta o decisión fiscal de jubilación?','Confirm actual event dates and deadlines before assuming a planning option is available.','Confirma fechas y plazos antes de suponer que existe una opción.',{when:{field:'changes',values:['sale_planned','retirement']},options:[['soon','Within 3 months','Dentro de 3 meses'],['year','In 4–12 months','En 4–12 meses'],['later','Later / exploring','Más adelante / explorando']],reviewValues:['soon']}))
const nonBeneficiaryGoals=['understand','income','compare','unsure','unknown']
const mainService=['civilian','uniformed','former','other','unknown']
SPECIALTY_CARDS.tsp.questions=SPECIALTY_CARDS.tsp.questions.map(q=>['timeline','pension','loan','income_sources','income_review','healthcare_review','beneficiaries'].includes(q.id)?{...q,whenAll:[...(q.whenAll??[]),{field:'goal',values:nonBeneficiaryGoals},{field:'service',values:mainService}]}:q)
SPECIALTY_CARDS.tsp.questions.push(
 choice('inherited_records','Have the beneficiary designation, account records, and your account status been reviewed?','¿Se revisaron designación de beneficiario, registros y estado de tu cuenta?','Confirm beneficiary status and account documentation directly with TSP before choosing any action.','Confirma estado de beneficiario y documentos con TSP antes de elegir una acción.',{whenAny:[{field:'goal',values:['beneficiary']},{field:'service',values:['beneficiary']}],reviewValues:['no']}),
 choice('inherited_options','Have applicable inherited-account distribution options and deadlines been explained to you?','¿Te explicaron opciones y plazos aplicables de distribución de cuenta heredada?','Review beneficiary-specific rules, dates, taxes, and options with TSP and a qualified specialist. Do not apply ordinary account-owner rules automatically.','Revisa reglas específicas, fechas, impuestos y opciones con TSP y un especialista. No apliques automáticamente reglas del titular original.',{whenAny:[{field:'goal',values:['beneficiary']},{field:'service',values:['beneficiary']}],reviewValues:['no']}))
